def taller_within(a: list[int], k: int) -> list[int]:
    n = len(a)
    if k == 0:
        return [0] * n

    vals = sorted(set(a))
    rank = {v: i + 1 for i, v in enumerate(vals)}
    m = len(vals)
    tree = [0] * (m + 1)
    res = [0] * n
    size = 0

    def update(i, delta):
        while i <= m:
            tree[i] += delta
            i += i & -i

    def query(i):
        s = 0
        while i > 0:
            s += tree[i]
            i -= i & -i
        return s

    for i in range(n):
        if i >= 1:
            update(rank[a[i - 1]], 1)
            size += 1
        if i - k - 1 >= 0:
            update(rank[a[i - k - 1]], -1)
            size -= 1
        res[i] = size - query(rank[a[i]])

    return res
